var mod3 = {
 id:"m3", n:3, title:"Emergências clínicas", icon:"pulse",
 intro:"Nem toda emergência vem de acidente. Um colega pode convulsionar na aula, desmaiar na fila ou passar mal no culto. Saber reconhecer o que está acontecendo e agir com calma protege a pessoa até o socorro chegar.",
 objectives:["Reconhecer uma convulsão e aplicar condutas seguras","Reconhecer um desmaio e saber o que fazer","Identificar sinais de alerta de AVC e infarto","Reconhecer sinais de hipoglicemia leve","Saber quando acionar o 192 em emergências clínicas"],
 sections:[
  {id:"m3s1", title:"Convulsões: reconhecer", body:[
   "A convulsão acontece por uma descarga elétrica desordenada no cérebro. A pessoa pode ficar rígida, cair, ter movimentos bruscos e repetitivos, perder a consciência, babar e, às vezes, perder o controle da urina. Pode ter causas diferentes, como epilepsia, febre alta em crianças, pancada na cabeça ou outras doenças.",
   "A maioria das convulsões passa sozinha em poucos minutos. É assustador de assistir, mas você não precisa tentar parar a crise. Seu papel é proteger a pessoa de se machucar, cronometrar o tempo e chamar ajuda quando necessário. Depois, ela costuma ficar sonolenta e confusa, o que é esperado."
  ]},
  {id:"m3s2", title:"Convulsões: o que fazer", body:[
   "Durante a crise, afaste objetos que possam machucar, como cadeiras e mesas, e apoie a cabeça com algo macio, como uma mochila ou casaco dobrado. Afrouxe roupas apertadas no pescoço e marque o horário. Peça aos curiosos que se afastem para dar privacidade. Fique perto e fale com calma.",
   "Não segure a pessoa, não coloque nada na boca dela (nem colher, nem pano, nem dedo) e não dê água. Quando os movimentos pararem, vire a pessoa de lado para ajudar na respiração e na saída de saliva. Ligue para o 192 se durar mais de 5 minutos, for a primeira vez, houver lesão, dificuldade de respirar, gestante ou se a crise se repetir."
  ], callout:{type:"warn", text:"Nunca segure a pessoa e nunca coloque nada na boca durante a convulsão."}},
  {id:"m3s3", title:"Desmaios", body:[
   "O desmaio é uma perda de consciência breve, geralmente por queda temporária do fluxo de sangue no cérebro. Pode vir após ficar muito tempo em pé, calor, jejum, susto, dor ou sol forte. Antes de desmaiar, a pessoa costuma sentir tontura, suor frio, palidez, visão escurecida ou fraqueza. Ela costuma acordar em instantes.",
   "Se perceber que alguém vai desmaiar, ajude a deitar ou sentar. Se já desmaiou, deite a pessoa de barriga para cima, eleve as pernas, afrouxe a roupa e deixe o ambiente ventilado. Se ela não acordar em cerca de 1 minuto, ou não respirar normalmente, ligue para o 192 e comece compressões, se não responder e não respirar normalmente."
  ], bullets:["Deitar e elevar as pernas","Afrouxar a roupa e ventilar o ambiente","Não dar comida ou bebida até acordar totalmente","192 se não acordar em cerca de 1 minuto"]},
  {id:"m3s4", title:"AVC e infarto: sinais de alerta", body:[
   "O AVC acontece quando falta sangue em uma parte do cérebro. Sinais comuns: rosto torto ou boca caída de um lado, fraqueza ou formigamento em um braço ou perna, fala enrolada ou confusa e dor de cabeça súbita e muito forte. Quanto mais rápido o atendimento, melhor. Ligue para o 192 e anote o horário em que os sinais começaram.",
   "O infarto ocorre quando falta sangue para o coração. Sinais: dor ou pressão no peito, que pode irradiar para braço, ombro, costas ou mandíbula, falta de ar, suor frio, náusea e mal-estar. Em ambos, não espere melhorar, acione o 192, mantenha a pessoa em repouso e não dê remédio nem comida. Se parar de responder e respirar, inicie compressões."
  ], callout:{type:"warn", text:"Rosto torto, braço fraco, fala alterada ou dor no peito: ligue 192 imediatamente."}},
  {id:"m3s5", title:"Hipoglicemia leve: reconhecer", body:[
   "A hipoglicemia é a queda do açúcar no sangue, mais comum em pessoas com diabetes. Sinais: tremores, suor frio, fome súbita, tontura, irritação, palidez, dor de cabeça e confusão. Isso pode acontecer, por exemplo, em uma criança diabética que ficou muito tempo sem comer durante uma gincana.",
   "Seu papel é reconhecer e acionar ajuda: ligue para o 192, mantenha a pessoa sentada ou deitada, e siga as orientações do atendente. Se ela estiver confusa, sonolenta ou inconsciente, não dê nada pela boca, pois há risco de engasgo. Avise um adulto responsável e fique ao lado até a equipe chegar."
  ]}
 ],
 examples:[
  {title:"Convulsão na sala de aula", env:"escola", text:"Um colega cai no chão e começa a se debater. Você afasta carteiras, coloca a mochila sob a cabeça dele e pede que alguém marque o horário e chame o professor. Não o segura nem coloca nada na boca. Quando os movimentos param, você o vira de lado e liga para o 192, pois foi a primeira vez que isso aconteceu."},
  {title:"Desmaio no calor", env:"ar livre", text:"Durante uma caminhada em dia de sol forte, uma colega fica pálida, suada e cai desmaiada. Você a leva para a sombra, deita-a de barriga para cima, eleva as pernas e afrouxa a roupa. Ela acorda em menos de um minuto, mas você avisa um adulto e mantém a observação até ela se recuperar."}
 ],
 summary:["Na convulsão: proteger, apoiar a cabeça, não segurar e não colocar nada na boca","Cronometrar e ligar 192 se passar de 5 minutos, 1ª vez, lesão ou repetição","Depois da convulsão, virar a pessoa de lado","No desmaio: deitar, elevar pernas, ventilar; 192 se não acordar em cerca de 1 minuto","AVC e infarto: reconhecer os sinais e ligar 192 sem demora","Hipoglicemia: reconhecer, chamar ajuda e nada pela boca se estiver confusa"],
 extras:[
  {title:"Mito x Verdade", text:"Mito: a pessoa em convulsão pode engolir a língua. Verdade: isso não acontece. Colocar objetos na boca machuca e dificulta a respiração."},
  {title:"Sinais do AVC: lembrete", text:"Observe rosto (boca torta), braços (um cai ou fica fraco) e fala (enrolada). Se algum estiver alterado, ligue 192 e anote o horário."},
  {title:"Checklist da convulsão", text:"Afastar objetos, apoiar a cabeça, marcar o tempo, não segurar, nada na boca, virar de lado quando parar, 192 se houver sinais de gravidade."}
 ],
 cards:[
  {q:"O que fazer durante uma convulsão?", a:"Proteger de ferimentos, apoiar a cabeça, afastar objetos, cronometrar e não segurar."},
  {q:"Pode colocar algo na boca na convulsão?", a:"Não. Nunca coloque objetos, pano ou dedos. Isso causa lesões e dificulta a respiração."},
  {q:"Quando ligar 192 na convulsão?", a:"Mais de 5 minutos, primeira vez, lesão, dificuldade de respirar, gestante ou repetição."},
  {q:"Conduta no desmaio", a:"Deitar, elevar as pernas, afrouxar a roupa e ventilar; 192 se não acordar em cerca de 1 minuto."},
  {q:"Sinais de alerta de AVC", a:"Boca torta, fraqueza em braço ou perna, fala alterada. Ligue 192 e anote o horário."},
  {q:"Sinais de infarto", a:"Dor ou pressão no peito, falta de ar, suor frio, dor que irradia para braço ou mandíbula."}
 ],
 activity:[
  {id:"m3a1", type:"mc", q:"Uma pessoa está convulsionando. Qual conduta é correta?", options:["Segurá-la com força","Colocar um pano na boca","Afastar objetos e apoiar a cabeça","Dar água para acalmá-la"], answer:2, exp:"Proteger da lesão é o essencial. Segurar ou colocar algo na boca é perigoso."},
  {id:"m3a2", type:"tf", q:"Uma convulsão que dura mais de 5 minutos exige ligar para o 192.", answer:true, exp:"Crises longas são emergência. Cronometrar ajuda a decidir e informar o atendente."},
  {id:"m3a3", type:"short", q:"Em qual posição você vira a pessoa quando a convulsão termina?", answers:["de lado","lateral"], exp:"Virar de lado ajuda a respirar e a saliva escorrer, evitando engasgo."},
  {id:"m3a4", type:"match", q:"Relacione o sinal à emergência provável.", pairs:[["Boca torta e fala enrolada","AVC"],["Dor no peito com suor frio","Infarto"],["Tremor, fome e suor em diabético","Hipoglicemia"],["Palidez, tontura e queda breve","Desmaio"]], exp:"Reconhecer sinais agiliza a ligação para o 192. Você não precisa de diagnóstico, só de atenção."},
  {id:"m3a5", type:"seq", q:"Ordene a conduta diante de um desmaio.", items:["Verificar a segurança e a resposta","Deitar a pessoa de barriga para cima","Elevar as pernas","Afrouxar a roupa e ventilar","Ligar 192 se não acordar em cerca de 1 minuto"], exp:"Essas medidas favorecem a circulação para o cérebro e a recuperação."},
  {id:"m3a6", type:"essay", q:"Explique por que não se deve segurar nem colocar objetos na boca de quem convulsiona.", exp:"Esperado: segurar pode causar fraturas e lesões; objetos na boca machucam dentes e língua e obstruem a respiração; a língua não é engolida. Conduta: proteger, apoiar a cabeça, cronometrar."}
 ],
 assessment:[
  {id:"m3s1", type:"mc", q:"Qual destes é um sinal de alerta de AVC?", options:["Soluço","Rosto torto e fala enrolada","Espirros seguidos","Coceira nos olhos"], answer:1, exp:"Boca caída, fraqueza em braço ou perna e fala alterada pedem 192 imediato."},
  {id:"m3s2", type:"mc", q:"Após o fim da convulsão, a pessoa está respirando e sonolenta. O que fazer?", options:["Dar água e comida","Sacudir para acordar","Virar de lado e observar","Deixá-la de barriga para cima sem vigiar"], answer:2, exp:"Posição de lado ajuda na respiração e evita engasgo. Observe e chame o 192 se houver critério."},
  {id:"m3s3", type:"mc", q:"Quando ligar 192 diante de um desmaio?", options:["Sempre após 10 minutos","Se não acordar em cerca de 1 minuto ou não respirar normalmente","Nunca, desmaio é normal","Só se a pessoa pedir"], answer:1, exp:"Desmaio breve costuma passar rapidamente. Persistência ou ausência de respiração normal exige 192."},
  {id:"m3s4", type:"tf", q:"Na hipoglicemia, se a pessoa estiver confusa ou inconsciente, você deve colocar comida em sua boca.", answer:false, exp:"Não dê nada pela boca a quem está confuso ou inconsciente, pois há risco de engasgo. Ligue 192."},
  {id:"m3s5", type:"err", q:"Encontre a afirmação INCORRETA.", items:["Em convulsão, deve-se cronometrar o tempo","No desmaio, pode-se elevar as pernas","Na convulsão, deve-se colocar uma colher na boca","No infarto, deve-se ligar para o 192"], answer:2, exp:"Nunca coloque objetos na boca de quem convulsiona: isso machuca e atrapalha a respiração."},
  {id:"m3s6", type:"short", q:"Quantos minutos de convulsão exigem ligar para o 192 (mais de...)?", answers:["5","cinco"], exp:"Convulsão com mais de 5 minutos é emergência e deve ser informada ao 192."}
 ]
};

var mod4 = {
 id:"m4", n:4, title:"Obstrução das vias aéreas", icon:"wind",
 intro:"Um pedaço de comida, uma bala, um brinquedo: coisas pequenas podem bloquear a passagem do ar. O engasgo assusta, mas tem solução. Saber distinguir entre engasgo leve e grave define o que fazer.",
 objectives:["Definir obstrução das vias aéreas e suas causas","Reconhecer engasgo leve e engasgo grave","Aplicar a conduta correta para adulto, criança e lactente","Saber o que fazer se a vítima ficar inconsciente","Acionar o 192 na hora certa"],
 sections:[
  {id:"m4s1", title:"O que é obstrução e quais as causas", body:[
   "A obstrução das vias aéreas, ou engasgo, acontece quando algo bloqueia a passagem do ar pela garganta ou pela traqueia. Pode ser parcial, quando ainda passa um pouco de ar, ou total, quando o ar não passa. Sem ar, a pessoa pode perder a consciência em poucos minutos, por isso é preciso agir rápido.",
   "As causas mais comuns são alimentos mal mastigados, falar ou rir enquanto come, balas, pedaços de brinquedos, moedas, tampas de caneta e líquidos engolidos de forma errada. Em lactentes e crianças pequenas, qualquer objeto pequeno que vai à boca é risco. Vigie e evite alimentos duros ou redondos nessa faixa etária."
  ]},
  {id:"m4s2", title:"Engasgo leve (obstrução parcial)", body:[
   "No engasgo leve, a pessoa consegue tossir, falar ou respirar, mesmo com esforço. A tosse é forte e ela está alerta. Isso significa que passa ar. A tosse é o mecanismo mais eficiente do corpo para expulsar o objeto, então o melhor é deixar a pessoa tossir.",
   "Fique ao lado, incentive-a a continuar tossindo e observe com atenção. Não bata nas costas e não dê água, pois isso pode empurrar o objeto para dentro. Se a tosse perder a força, a pessoa não conseguir mais falar ou respirar, ou o objeto não sair, considere engasgo grave e acione o 192."
  ], callout:{type:"tip", text:"Engasgo leve: estimule a tosse. Não bata nas costas."}},
  {id:"m4s3", title:"Engasgo grave em adulto e criança", body:[
   "No engasgo grave, a pessoa não consegue falar, tossir ou respirar. Muitas vezes leva as mãos ao pescoço, fica com o rosto vermelho ou arroxeado e com expressão de pânico. É emergência. Peça para alguém ligar para o 192 imediatamente e comece a manobra, sem perder tempo.",
   "Em adulto e criança, alterne 5 tapas firmes nas costas, entre as escápulas, com 5 compressões abdominais (manobra de Heimlich): fique atrás, posicione o punho acima do umbigo, abaixo das costelas, e puxe com força para dentro e para cima. Repita até o objeto sair ou a vítima ficar inconsciente. Em gestantes e obesos, compressões no tórax."
  ], bullets:["5 tapas nas costas","5 compressões abdominais","Repetir alternando","Se ficar inconsciente: 192 e RCP"]},
  {id:"m4s4", title:"Engasgo grave em lactente", body:[
   "Lactente é o bebê com menos de 1 ano. No engasgo grave, ele não chora, não tosse e pode ficar arroxeado. Nunca faça a manobra de Heimlich em bebê. Segure-o de bruços sobre seu antebraço, apoiado na coxa, com a cabeça mais baixa que o corpo, apoiando o queixo com a mão.",
   "Dê 5 tapas firmes entre as escápulas. Depois, vire o bebê de barriga para cima, com a cabeça mais baixa, e faça 5 compressões no centro do peito com 2 dedos, cerca de 4 cm de profundidade. Alterne os ciclos até o objeto sair. Peça a alguém que ligue para o 192. Siga o protocolo ensinado pelo instrutor presencial."
  ]},
  {id:"m4s5", title:"Se a vítima ficar inconsciente", body:[
   "Se a vítima ficar inconsciente e não respirar normalmente, deite-a no chão em local firme, confirme que alguém ligou para o 192 e inicie a RCP com compressões no centro do peito. As compressões também podem ajudar a mover o objeto. Se você é leigo e não treinado, faça apenas compressões.",
   "Se for treinado, faça compressões e ventilações (30:2). Antes de cada ventilação, abra a boca e olhe: se enxergar claramente o objeto, retire-o. Nunca faça varredura às cegas com o dedo. Continue até a equipe do 192 chegar ou a vítima voltar a respirar e se movimentar."
  ], callout:{type:"warn", text:"Nunca enfie o dedo às cegas na garganta: pode empurrar o objeto."}}
 ],
 examples:[
  {title:"Engasgo na cantina", env:"escola", text:"Durante o lanche, um colega leva as mãos ao pescoço e não consegue falar nem tossir. Você pede que alguém ligue para o 192, se posiciona atrás dele, dá 5 tapas nas costas e 5 compressões abdominais, alternando. Depois de algumas séries, o pedaço de pão sai e ele volta a respirar. Mesmo assim, ele deve ser avaliado."},
  {title:"Bebê engasgado na casa de parentes", env:"casa", text:"Seu priminho de 8 meses põe uma tampinha na boca e fica sem chorar e arroxeado. Você pede ajuda ao 192 e, com um adulto, o apoia de bruços no antebraço, cabeça baixa, e dá 5 tapas nas costas. Depois o vira e faz 5 compressões no peito com 2 dedos, alternando até a tampinha sair."}
 ],
 summary:["Obstrução das vias aéreas é bloqueio da passagem do ar","Engasgo leve: a pessoa tosse e fala; estimule a tosse","Engasgo grave: não fala, não tosse, não respira; 192 imediato","Adulto e criança: 5 tapas nas costas e 5 compressões abdominais","Lactente: 5 tapas nas costas e 5 compressões no peito com 2 dedos","Se ficar inconsciente: 192 e RCP"],
 extras:[
  {title:"Mito x Verdade", text:"Mito: dar água ajuda a desengasgar. Verdade: líquido pode piorar. No engasgo leve, estimule a tosse; no grave, faça as manobras."},
  {title:"Prevenção no dia a dia", text:"Mastigue bem, não fale com a boca cheia, corte alimentos para crianças pequenas e mantenha objetos pequenos longe de bebês."},
  {title:"Sinal universal", text:"Levar as mãos ao pescoço é o sinal universal de engasgo. Ao ver isso, pergunte: \"Você está engasgado?\". Se a pessoa não consegue falar, aja."}
 ],
 cards:[
  {q:"Engasgo leve: como reconhecer?", a:"A pessoa tosse forte, consegue falar e respirar. Estimule a tosse, sem bater nas costas."},
  {q:"Engasgo grave: como reconhecer?", a:"Não fala, não tosse, não respira; leva as mãos ao pescoço e pode arroxear."},
  {q:"Conduta no engasgo grave de adulto e criança", a:"5 tapas nas costas alternados com 5 compressões abdominais, e 192."},
  {q:"Conduta no engasgo grave de lactente", a:"5 tapas nas costas e 5 compressões no peito com 2 dedos, alternando."},
  {q:"Pode fazer Heimlich em bebê?", a:"Não. Em lactente, use tapas nas costas e compressões no peito."},
  {q:"Se a vítima ficar inconsciente", a:"Ligar 192 e iniciar RCP com compressões no centro do peito."}
 ],
 activity:[
  {id:"m4a1", type:"mc", q:"Um colega tosse forte e consegue falar após engasgar com um biscoito. Qual a melhor conduta?", options:["Bater forte nas costas","Dar um copo de água","Estimular a tosse e observar","Fazer compressões abdominais"], answer:2, exp:"Se a tosse é eficaz, ela é o melhor recurso. Intervenha apenas se piorar."},
  {id:"m4a2", type:"tf", q:"Em um bebê com engasgo grave, deve-se fazer a manobra de Heimlich.", answer:false, exp:"Em lactentes use 5 tapas nas costas e 5 compressões no peito com 2 dedos."},
  {id:"m4a3", type:"short", q:"Quantos tapas nas costas se dão em cada série no engasgo grave?", answers:["5","cinco"], exp:"São 5 tapas nas costas alternados com 5 compressões abdominais (ou torácicas no lactente)."},
  {id:"m4a4", type:"match", q:"Relacione a vítima à conduta no engasgo grave.", pairs:[["Adulto","Tapas nas costas e compressões abdominais"],["Criança","Tapas nas costas e compressões abdominais"],["Lactente","Tapas nas costas e compressões no peito com 2 dedos"],["Inconsciente","192 e RCP"]], exp:"A conduta varia conforme a idade e o nível de consciência."},
  {id:"m4a5", type:"seq", q:"Ordene a conduta no engasgo grave de adulto.", items:["Reconhecer: não fala, não tosse, não respira","Pedir que liguem para o 192","Dar 5 tapas nas costas","Fazer 5 compressões abdominais","Alternar até sair o objeto ou a vítima desmaiar"], exp:"As séries alternadas aumentam a chance de expulsar o objeto."},
  {id:"m4a6", type:"essay", q:"Explique a diferença entre engasgo leve e engasgo grave e o que fazer em cada caso.", exp:"Esperado: leve = tosse, fala e respira, conduta é estimular a tosse; grave = não fala, não tosse, não respira, conduta é 192 e 5 tapas + 5 compressões abdominais (lactente: tórax). Se inconsciente, RCP."}
 ],
 assessment:[
  {id:"m4s1", type:"mc", q:"Qual é um sinal de engasgo grave?", options:["Tosse forte e fala clara","Pessoa não consegue falar nem tossir e leva as mãos ao pescoço","Voz rouca depois de gritar","Soluço"], answer:1, exp:"Se o ar não passa, não há voz nem tosse. É preciso agir rápido."},
  {id:"m4s2", type:"mc", q:"Onde se dão os tapas em um adulto com engasgo grave?", options:["Na barriga","Na nuca","Entre as escápulas, nas costas","No peito"], answer:2, exp:"Os tapas são dados firmes nas costas, entre as escápulas, alternando com compressões abdominais."},
  {id:"m4s3", type:"mc", q:"Adulto com engasgo grave fica inconsciente. O que fazer?", options:["Dar tapas no rosto","Dar água","Ligar 192 e iniciar a RCP","Esperar acordar"], answer:2, exp:"Inconsciente e sem respirar: 192 e compressões no centro do peito."},
  {id:"m4s4", type:"tf", q:"No engasgo leve, deve-se bater nas costas da pessoa para ajudar.", answer:false, exp:"No engasgo leve, a tosse é eficaz. Bater pode deslocar o objeto e piorar a situação."},
  {id:"m4s5", type:"err", q:"Encontre a afirmação INCORRETA.", items:["Em lactente, usa-se tapas nas costas e compressões no peito com 2 dedos","No engasgo grave, é preciso acionar o 192","Em bebês, faz-se compressão abdominal de Heimlich","Nunca se deve fazer varredura às cegas com o dedo"], answer:2, exp:"Heimlich não é usado em lactentes. A conduta é tapas nas costas e compressões torácicas."},
  {id:"m4s6", type:"short", q:"Quantas compressões abdominais alternam com os tapas nas costas?", answers:["5","cinco"], exp:"São 5 tapas e 5 compressões, alternados até desobstruir ou a vítima ficar inconsciente."}
 ]
};

var mod5 = {
 id:"m5", n:5, title:"Emergências traumáticas", icon:"alert",
 intro:"Quedas na quadra, tombos de bicicleta, batidas de cabeça, torções no futebol. Os traumas são comuns na vida dos adolescentes. Saber o que fazer, e principalmente o que evitar, impede que uma lesão se torne mais grave.",
 objectives:["Definir trauma e reconhecer as situações mais comuns","Identificar sinais de gravidade","Aplicar cuidados iniciais e prevenir agravamentos","Agir diante de TCE e suspeita de lesão na coluna","Cuidar de entorses, luxações e ferimentos com segurança"],
 sections:[
  {id:"m5s1", title:"O que é trauma e onde acontece", body:[
   "Trauma é uma lesão causada por uma força externa ao corpo, como pancada, queda, batida, queimadura ou corte. Pode atingir pele, músculos, ossos, articulações e órgãos internos. Algumas lesões são visíveis, outras ficam escondidas, como uma lesão interna ou uma pancada na cabeça que parecia leve.",
   "As situações mais comuns são quedas (de escada, bicicleta, skate ou árvore), acidentes de trânsito, pancadas durante esportes, brincadeiras, cortes e acidentes domésticos. O que importa é perceber que o mecanismo do acidente indica a gravidade: queda de grande altura ou batida forte merecem atenção maior, mesmo se a vítima disser que está bem."
  ]},
  {id:"m5s2", title:"Sinais de gravidade e cuidados iniciais", body:[
   "Considere grave quando houver: perda de consciência, confusão, dificuldade para respirar, sangramento intenso, dor forte, deformidade em ossos, vômitos repetidos, convulsão, paralisia ou formigamento, ou queda de grande altura. Em qualquer um desses casos, ligue para o 192. Na dúvida, ligue.",
   "Os cuidados iniciais seguem a lógica: segurança da cena, chamar ajuda, avaliar consciência e respiração, controlar sangramento visível com pressão direta e manter a pessoa calma e aquecida. Não dê comida nem bebida, pois a vítima pode precisar de cirurgia. Observe a pessoa até o socorro chegar e informe o que viu."
  ]},
  {id:"m5s3", title:"Prevenir agravamentos", body:[
   "A regra é: não mover sem necessidade. Mexer em uma vítima com lesão na coluna pode causar dano permanente. Só mova em perigo iminente, como fogo, desabamento, risco de atropelamento ou gás. Nesse caso, arraste a vítima pelo eixo longo do corpo, mantendo cabeça, pescoço e tronco alinhados.",
   "Em acidentes de moto, o leigo não deve retirar o capacete, salvo se for necessário para a via aérea ou para a RCP, e, se possível, apenas por quem foi treinado. Também evite levantar a vítima \"para ver se consegue andar\", dar comida ou bebida e retirar objetos cravados. Cada movimento desnecessário pode agravar o quadro."
  ], callout:{type:"warn", text:"Na dúvida sobre coluna, não mova. Aguarde o socorro."}},
  {id:"m5s4", title:"Trauma de cabeça (TCE) e suspeita de lesão na coluna", body:[
   "O traumatismo cranioencefálico (TCE) é uma pancada na cabeça. Mesmo parecendo leve, pode ter consequências. Sinais de gravidade: perda de consciência, vômitos, sonolência, confusão, dor de cabeça forte, convulsão, saída de líquido ou sangue pelo ouvido ou nariz, e diferença no tamanho das pupilas. Nesses casos, ligue 192 e não dê alimento ou bebida.",
   "Suspeite de lesão na coluna em quedas de altura, acidentes de trânsito, mergulhos e batidas fortes na cabeça ou pescoço, ou se houver dor no pescoço ou nas costas, formigamento ou perda de força. Peça à vítima que fique imóvel, apoie a cabeça sem tracionar, ligue 192 e aguarde. Não flexione nem gire o pescoço."
  ], bullets:["Vômitos, sonolência ou confusão após pancada","Convulsão","Líquido ou sangue saindo pelo ouvido ou nariz","Dor no pescoço, formigamento ou perda de força"]},
  {id:"m5s5", title:"Entorses, luxações, fraturas e ferimentos", body:[
   "A entorse é uma torção de articulação (como o tornozelo); a luxação é quando o osso sai do lugar na articulação; a fratura é a quebra do osso. Sinais comuns: dor, inchaço, deformidade e dificuldade de movimentar. Imobilize na posição encontrada, sem tentar alinhar nem empurrar o osso, e aplique frio com pano entre o gelo e a pele. Se for grave, ligue 192.",
   "Em ferimentos, lave as mãos ou use luvas, controle o sangramento com pressão direta e use pano limpo. Em fratura exposta, cubra com pano limpo, sem empurrar o osso de volta. Não remova objeto cravado: estabilize-o e procure atendimento. Ferimentos profundos, sujos, em rosto ou com sangramento que não para precisam de avaliação profissional."
  ], callout:{type:"tip", text:"Imobilize como encontrou. Nunca tente \"colocar o osso no lugar\"."}}
 ],
 examples:[
  {title:"Pancada de cabeça no jogo", env:"quadra", text:"Dois jogadores batem a cabeça. Um deles diz estar bem, mas começa a ficar sonolento e vomita. Você leva isso a sério: avisa o professor, liga para o 192 e pede que ele fique parado, sem comer ou beber nada. Você informa que houve batida na cabeça, sonolência e vômitos, sinais de gravidade."},
  {title:"Queda de skate no parque", env:"parque", text:"Um colega cai do skate e relata dor no tornozelo, que incha rápido. Você pede que não apoie o pé e o ajuda a sentar. Com um casaco enrolado e uma tira de tecido, imobiliza na posição encontrada e coloca gelo embrulhado em pano. Chama um adulto e procura atendimento, sem tentar alinhar o pé."}
 ],
 summary:["Trauma é lesão causada por força externa: queda, pancada, batida, corte","O mecanismo do acidente indica a gravidade","Sinais graves: perda de consciência, vômitos, confusão, sangramento intenso, deformidade","Não mova suspeita de lesão na coluna, salvo perigo iminente","Imobilize fraturas como encontrou, sem alinhar; frio com pano entre gelo e pele","Sem alimento ou bebida em vítima de trauma grave"],
 extras:[
  {title:"Mito x Verdade", text:"Mito: se a pessoa se mexe e fala, não tem lesão na coluna. Verdade: ela pode ter lesão mesmo assim. Mecanismo de acidente e dor guiam a suspeita."},
  {title:"Checklist do trauma", text:"Cena segura, chamar 192 se houver gravidade, controlar sangramento, não mover, não dar comida ou bebida, manter calma e aquecida e observar."},
  {title:"Prevenção", text:"Use capacete na bicicleta e no skate, cinto de segurança, calçado adequado no esporte, e aqueça antes de treinar. Prevenir é o melhor primeiro socorro."}
 ],
 cards:[
  {q:"O que é trauma?", a:"Lesão causada por força externa, como queda, pancada, batida ou corte."},
  {q:"Sinais de gravidade no TCE", a:"Vômitos, sonolência, confusão, convulsão e líquido ou sangue saindo pelo ouvido ou nariz."},
  {q:"Suspeita de lesão na coluna: o que fazer?", a:"Não mover, manter imóvel, apoiar a cabeça e ligar 192."},
  {q:"Quando mover a vítima?", a:"Só em perigo iminente: fogo, desabamento, trânsito ou gás; arrastar alinhando cabeça, pescoço e tronco."},
  {q:"Como imobilizar uma fratura?", a:"Na posição encontrada, sem alinhar nem empurrar o osso, com frio protegido por pano."},
  {q:"Objeto cravado: o que fazer?", a:"Não remover. Estabilizar o objeto, controlar o sangramento ao redor e chamar ajuda."}
 ],
 activity:[
  {id:"m5a1", type:"mc", q:"Uma vítima de queda de escada reclama de dor no pescoço. Qual a conduta?", options:["Levantá-la para andar","Mantê-la imóvel e ligar 192","Girar o pescoço para checar","Dar água"], answer:1, exp:"Dor no pescoço após queda sugere lesão na coluna. Não mova e chame 192."},
  {id:"m5a2", type:"tf", q:"Em fratura, o socorrista leigo deve tentar colocar o osso no lugar.", answer:false, exp:"Imobilize na posição encontrada, sem alinhar nem empurrar o osso."},
  {id:"m5a3", type:"short", q:"Qual a sigla para traumatismo na cabeça?", answers:["tce","traumatismo cranioencefalico"], exp:"TCE é o traumatismo cranioencefálico, pancada na cabeça que pode ter consequências mesmo parecendo leve."},
  {id:"m5a4", type:"match", q:"Relacione o problema ao cuidado inicial.", pairs:[["Suspeita de coluna","Manter imóvel e ligar 192"],["Entorse","Imobilizar e aplicar frio protegido"],["Fratura exposta","Cobrir com pano limpo, sem empurrar"],["Sangramento visível","Pressão direta com pano limpo"]], exp:"Cada lesão pede um cuidado simples e seguro, sempre com acionamento de ajuda se houver gravidade."},
  {id:"m5a5", type:"seq", q:"Ordene o atendimento a um colega que caiu da bicicleta.", items:["Verificar se a cena está segura","Chamar e checar se responde","Ligar 192 se houver sinal de gravidade","Controlar sangramento visível","Manter a vítima imóvel e aquecida até a ajuda"], exp:"Segurança, avaliação, chamada de ajuda e cuidados simples compõem a conduta."},
  {id:"m5a6", type:"essay", q:"Por que não devemos mover uma vítima com suspeita de lesão na coluna? Quando a exceção se aplica?", exp:"Esperado: movimentar pode causar ou agravar lesão na medula, com paralisia. Exceção: perigo iminente (fogo, desabamento, trânsito, gás), com arrasto pelo eixo longo, mantendo cabeça-pescoço-tronco alinhados."}
 ],
 assessment:[
  {id:"m5s1", type:"mc", q:"Qual é um sinal de gravidade após uma pancada na cabeça?", options:["Dor leve passageira","Vômitos e sonolência","Vermelhidão leve na pele","Sede"], answer:1, exp:"Vômitos, sonolência, confusão e convulsão indicam possível lesão cerebral. Ligue 192."},
  {id:"m5s2", type:"mc", q:"Como deve ser feito o frio local em uma entorse?", options:["Gelo direto na pele","Gelo envolvido em pano","Água quente","Pomada com massagem"], answer:1, exp:"O pano evita queimadura por frio na pele. Gelo nunca deve ficar em contato direto."},
  {id:"m5s3", type:"mc", q:"Um objeto está cravado no braço de uma vítima. Qual a conduta?", options:["Retirar rapidamente","Girar para soltar","Não retirar e estabilizar, chamando ajuda","Empurrar para dentro"], answer:2, exp:"Retirar pode aumentar o sangramento. Estabilize e chame ajuda."},
  {id:"m5s4", type:"tf", q:"Em acidente de moto, o leigo deve retirar o capacete sempre que possível.", answer:false, exp:"O capacete só é retirado se for necessário para via aérea ou RCP, preferencialmente por quem foi treinado."},
  {id:"m5s5", type:"err", q:"Encontre a afirmação INCORRETA.", items:["Suspeita de coluna: não mover a vítima sem necessidade","Vítima de trauma grave não deve receber comida ou bebida","Em fratura exposta, deve-se empurrar o osso para dentro","Só se move a vítima em perigo iminente"], answer:2, exp:"Nunca empurre o osso. Cubra com pano limpo e chame ajuda."},
  {id:"m5s6", type:"short", q:"Como se chama a lesão em que o osso sai do lugar na articulação?", answers:["luxacao","luxação"], exp:"Na luxação o osso sai da articulação. Imobilize e procure atendimento, sem tentar reduzi-la."}
 ]
};

var mod6 = {
 id:"m6", n:6, title:"Hemorragias", icon:"drop",
 intro:"Um corte, um nariz que sangra, uma queda no cascalho. Sangramento assusta, mas na maioria das vezes pode ser controlado com algo simples: um pano limpo e pressão. Saber agir rápido pode salvar uma vida.",
 objectives:["Definir hemorragia e diferenciar externa e interna","Reconhecer os tipos de sangramento","Identificar sinais e situações de risco","Aplicar os princípios gerais de controle de sangramento","Saber agir em sangramento nasal"],
 sections:[
  {id:"m6s1", title:"O que é hemorragia", body:[
   "Hemorragia é a saída de sangue dos vasos sanguíneos, em quantidade maior do que o corpo consegue repor. O sangue carrega oxigênio para todo o corpo. Quando se perde muito, o corpo não consegue manter a circulação e a pessoa pode entrar em estado de choque. Por isso, o controle precoce é prioridade.",
   "Nem todo sangramento é grave. Um arranhão sangra pouco e para sozinho. Mas um corte profundo ou lesão em vaso importante pode causar perda grande de sangue em poucos minutos. O que importa é a quantidade, a velocidade e a localização do sangramento, além do estado geral da vítima."
  ]},
  {id:"m6s2", title:"Hemorragia externa e interna", body:[
   "Na hemorragia externa, o sangue sai pelo corpo e você consegue ver: cortes, escoriações, fraturas expostas. É a mais fácil de reconhecer e controlar. Já na hemorragia interna, o sangue se acumula dentro do corpo e não aparece, como em uma pancada forte no abdômen ou em fraturas grandes.",
   "A hemorragia interna é perigosa porque passa despercebida. Suspeite quando houver trauma importante, dor forte, abdômen endurecido ou inchado, hematomas extensos, palidez, tontura e sinais de choque. Também pode haver sangue saindo pela boca, ouvido ou nariz. Nesses casos, ligue 192, mantenha a vítima deitada e não dê comida ou bebida."
  ], callout:{type:"warn", text:"Suspeita de hemorragia interna: 192, repouso e nada pela boca."}},
  {id:"m6s3", title:"Tipos de sangramento", body:[
   "Conforme o vaso lesado, o sangramento tem características diferentes. O capilar é o mais comum, em pequenos cortes: o sangue escorre devagar e costuma parar sozinho. O venoso é mais escuro e sai de forma contínua, como um fluxo. O arterial é vermelho vivo e sai em jatos, acompanhando os batimentos do coração.",
   "Na prática, você não precisa classificar com exatidão. O que importa é a gravidade: sangramento que jorra, encharca o pano rapidamente ou não para exige pressão imediata e ligação para o 192. Sangramento em jato é uma emergência. Quanto mais rápido o controle, menor a perda e maior a chance de recuperação."
  ], bullets:["Capilar: pequeno, escorre e para sozinho","Venoso: escuro e contínuo","Arterial: vermelho vivo e em jatos; emergência"]},
  {id:"m6s4", title:"Sinais de risco e estado de choque", body:[
   "Sinais de que a perda de sangue está grave: pele pálida, fria e suada, pulso rápido e fraco, respiração rápida, sede, tontura, sonolência, ansiedade e, depois, confusão. Esse conjunto é o estado de choque. Ele pode surgir em hemorragias externas grandes e internas. Ligue para o 192 imediatamente.",
   "Enquanto o socorro não chega, controle o sangramento visível, deite a vítima e, se não houver trauma de cabeça, coluna ou pernas nem dificuldade para respirar, eleve as pernas. Aqueça a pessoa com um casaco ou cobertor e não dê nada por via oral. Fale com calma e observe a respiração até a chegada da equipe."
  ]},
  {id:"m6s5", title:"Como controlar: princípios gerais e sangramento nasal", body:[
   "Princípios gerais: use luvas ou uma barreira, como sacola plástica, se possível. Aplique pressão direta firme com pano limpo diretamente sobre o ferimento e mantenha. Se o pano encharcar, não o retire: coloque mais panos por cima e continue pressionando. Não remova objeto cravado. Em ferida grave de braço ou perna que não para, o torniquete é último recurso, idealmente por quem foi treinado.",
   "No sangramento nasal (epistaxe), sente a pessoa, incline a cabeça levemente para frente, não para trás, e aperte as narinas por cerca de 10 minutos sem soltar para espiar. Respire pela boca. Se o sangramento não parar, ocorrer após pancada na cabeça ou a pessoa passar mal, ligue para o 192."
  ], callout:{type:"tip", text:"Pano limpo, pressão direta e firme. Se encharcar, ponha mais por cima."}}
 ],
 examples:[
  {title:"Corte na aula de educação física", env:"escola", text:"Um colega se corta no vidro de uma janela e o sangue escorre sem parar. Você pega um pano limpo, pressiona firmemente sobre o corte e pede para alguém chamar o professor. O pano encharca, então você coloca outro por cima, sem retirar o primeiro. Você mantém a pressão até a chegada da ajuda e liga para o 192 se o sangramento não cessar."},
  {title:"Nariz sangrando no acampamento", env:"campo", text:"Uma colega começa a sangrar pelo nariz durante o jogo. Você a ajuda a sentar, inclina a cabeça dela levemente para frente e pede para apertar as narinas por cerca de 10 minutos, respirando pela boca. O sangramento para. Se tivesse continuado ou houvesse pancada na cabeça, você teria ligado para o 192."}
 ],
 summary:["Hemorragia é perda de sangue dos vasos em grande quantidade","Externa é visível; interna fica escondida e é perigosa","Sangramento arterial é vermelho vivo e em jatos: emergência","Pressão direta com pano limpo; se encharcar, colocar mais por cima","Não remover objeto cravado; torniquete só como último recurso e de preferência por quem treinou","Nariz: sentar, inclinar para frente e apertar as narinas por cerca de 10 minutos"],
 extras:[
  {title:"Mito x Verdade", text:"Mito: jogar a cabeça para trás para parar sangramento nasal. Verdade: inclinar para frente evita engolir sangue e engasgo."},
  {title:"Checklist: sangramento", text:"Barreira ou luvas, pano limpo, pressão direta e firme, mais panos por cima se encharcar, 192 se grave, deitar e aquecer."},
  {title:"Curiosidade", text:"A pressão direta é a técnica mais importante e mais simples de controle de sangramento e funciona na grande maioria das situações."}
 ],
 cards:[
  {q:"O que é hemorragia?", a:"Saída de sangue dos vasos em grande quantidade, que pode levar ao estado de choque."},
  {q:"Hemorragia interna: sinais", a:"Dor forte, abdômen inchado, palidez, tontura e sinais de choque após trauma."},
  {q:"Sangramento arterial", a:"Vermelho vivo, em jatos, no ritmo do coração. Pressão imediata e 192."},
  {q:"Como controlar um sangramento?", a:"Pressão direta e firme com pano limpo; se encharcar, colocar mais por cima."},
  {q:"Sangramento nasal: conduta", a:"Sentar, inclinar para frente e apertar as narinas por cerca de 10 minutos."},
  {q:"Quando usar torniquete?", a:"Só como último recurso em hemorragia grave de membro, de preferência por quem foi treinado."}
 ],
 activity:[
  {id:"m6a1", type:"mc", q:"O pano usado para pressionar um ferimento ficou encharcado de sangue. O que fazer?", options:["Retirar e trocar por outro","Colocar mais panos por cima e continuar pressionando","Parar de pressionar","Lavar o ferimento sob a torneira"], answer:1, exp:"Retirar o pano pode arrancar o coágulo. Coloque mais por cima e mantenha a pressão."},
  {id:"m6a2", type:"tf", q:"No sangramento nasal, deve-se inclinar a cabeça para trás.", answer:false, exp:"A cabeça vai levemente para frente, para evitar engolir sangue e engasgar."},
  {id:"m6a3", type:"short", q:"Por quantos minutos, aproximadamente, se aperta o nariz no sangramento nasal?", answers:["10","dez"], exp:"Mantenha cerca de 10 minutos sem soltar para espiar."},
  {id:"m6a4", type:"match", q:"Relacione o tipo de sangramento à característica.", pairs:[["Capilar","Escorre devagar e costuma parar sozinho"],["Venoso","Escuro e contínuo"],["Arterial","Vermelho vivo e em jatos"],["Interno","Não aparece, sinais de choque"]], exp:"Reconhecer ajuda a avaliar a gravidade, mas a conduta é sempre controlar e chamar ajuda se grave."},
  {id:"m6a5", type:"seq", q:"Ordene o controle de um sangramento externo.", items:["Garantir a segurança da cena","Usar luvas ou barreira","Pressionar com pano limpo diretamente na ferida","Colocar mais panos se encharcar","Ligar 192 se grave e manter a vítima deitada"], exp:"Pressão direta é a medida central. Chamar ajuda cedo faz diferença."},
  {id:"m6a6", type:"essay", q:"Descreva os sinais de estado de choque por perda de sangue e o que fazer enquanto o socorro não chega.", exp:"Esperado: pele pálida, fria e suada, pulso rápido e fraco, respiração rápida, sonolência e ansiedade. Conduta: 192, controlar sangramento, deitar, elevar pernas (se sem trauma de cabeça, coluna, pernas ou dificuldade respiratória), aquecer, nada por via oral."}
 ],
 assessment:[
  {id:"m6s1", type:"mc", q:"Como é o sangramento arterial?", options:["Escuro e lento","Vermelho vivo e em jatos","Só gotas","Só em hematomas"], answer:1, exp:"O sangue arterial sai em jatos no ritmo do coração, o que exige ação imediata."},
  {id:"m6s2", type:"mc", q:"Qual é a conduta geral inicial para controlar um sangramento externo?", options:["Aplicar pasta de dente","Pressão direta com pano limpo","Lavar com álcool e esfregar","Aplicar torniquete sempre"], answer:1, exp:"Pressão direta é a medida mais simples e eficaz. O torniquete é só último recurso."},
  {id:"m6s3", type:"mc", q:"Sinal de gravidade após queda com sangramento:", options:["Pele pálida, fria e suada com pulso rápido","Coceira","Sede leve","Espirro"], answer:0, exp:"Pele pálida, fria e suada com pulso rápido indicam choque. Ligue 192."},
  {id:"m6s4", type:"tf", q:"Quando há um objeto cravado, o socorrista deve removê-lo para estancar o sangramento.", answer:false, exp:"Remover pode aumentar o sangramento. Estabilize o objeto e chame ajuda."},
  {id:"m6s5", type:"err", q:"Encontre a afirmação INCORRETA.", items:["Hemorragia interna pode não aparecer por fora","No sangramento nasal, inclina-se a cabeça para frente","No sangramento nasal, a cabeça deve ser jogada para trás","Torniquete é último recurso em sangramento grave de membro"], answer:2, exp:"Jogar a cabeça para trás faz engolir sangue. Incline levemente para frente."},
  {id:"m6s6", type:"short", q:"Qual condição grave pode surgir após grande perda de sangue?", answers:["choque","estado de choque"], exp:"O estado de choque ocorre quando a circulação não mantém o oxigênio nos órgãos. Exige 192."}
 ]
};

